def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        a_mid = k // 2 - 1 if len(a) >= k // 2 else len(a) - 1
        b_mid = k // 2 - 1 if len(b) >= k // 2 else len(b) - 1

        if a[a_mid] <= b[b_mid]:
            return kth_element(a[a_mid + 1:], b, k - (a_mid + 1))
        else:
            return kth_element(a, b[b_mid + 1:], k - (b_mid + 1))

    return kth_element(arr1, arr2, k)
