def move_num(input_string):
    # Separate the characters and digits into two lists
    chars = []
    digits = []

    for char in input_string:
        if char.isdigit():
            digits.append(char)
        else:
            chars.append(char)

    # Combine non-digit characters and digits
    return ''.join(chars) + ''.join(digits)

