def tuple_to_dict(input_tuple):
    """
    Converts a given tuple into a dictionary using adjacent elements as key-value pairs.

    Args:
    input_tuple (tuple): The input tuple with elements to be paired.

    Returns:
    dict: A dictionary with adjacent elements of the tuple as key-value pairs.
    """
    # Use dictionary comprehension to pair adjacent elements
    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple) - 1, 2)}

# Test cases
