def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys, 
    the value from dict3 overwrites dict2, and dict2 overwrites dict1.
    """
    merged = {}  # Start with an empty dictionary
    # Iterate through all dictionaries in the order dict1 -> dict2 -> dict3
    for dictionary in (dict1, dict2, dict3):
        merged.update(dictionary)  # Update the merged dictionary with the current dictionary
    return merged

